// The worker that owns the wasm engine. Point `openPdf` at it with `new Worker(url, { type: "module" })`
// (a bundler does this for `import Worker from "craftbridge/pdf/worker?worker"`).

// @ts-ignore the glue code is generated by scripts/build-wasm.sh, so it is absent until a build
import init, { Pdf } from "../../wasm/pdf/pdfcraft_wasm.js";
import { Engine, toEngineError, type WasmModule } from "./engine";
import type { Reply, Request } from "./protocol";

const scope = self as unknown as {
  onmessage: ((e: MessageEvent<Request>) => void) | null;
  postMessage(message: Reply, transfer?: Transferable[]): void;
};

let engine: Engine | null = null;
let ready: Promise<unknown> | null = null;

const wasm: WasmModule = {
  open: (bytes, password) => new Pdf(bytes, password ?? undefined),
};

scope.onmessage = async (e) => {
  const { id, ...call } = e.data;
  try {
    if (call.op === "open") {
      ready ??= init(call.wasmUrl ? { module_or_path: call.wasmUrl } : undefined);
      await ready;
      engine ??= new Engine(wasm);
    }
    if (!engine) throw toEngineError(new Error("the engine has not been opened"));
    const { value, transfer } = engine.handle(call);
    scope.postMessage({ id, ok: true, value }, transfer ?? []);
  } catch (err) {
    const error = toEngineError(err);
    scope.postMessage({ id, ok: false, code: error.code, message: error.message });
  }
};
